def binary_search_recursive(arr, target, lo=0, hi=None):
    if hi is None:
        hi = len(arr) - 1
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if arr[mid] == target:
        return mid
    if arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, hi)
    return binary_search_recursive(arr, target, lo, mid - 1)

# Example: binary_search_recursive([2,4,6,8,10], 8) -> 3
# Time: O(log n), Space: O(log n) recursion stack. Recursive divide and conquer.

