def search_2d(matrix, target):
    m, n = len(matrix), len(matrix[0])
    lo, hi = 0, m * n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        val = matrix[mid // n][mid % n]
        if val == target:
            return True
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

# Example: search_2d([[1,3,5],[7,9,11],[13,15,17]], 9) -> True
# Time: O(log(m*n)), Space: O(1). Virtual 1D binary search over the flattened matrix.

def int_sqrt(x):
    if x < 2:
        return x
    lo, hi = 1, x // 2
    result = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        square = mid * mid
        if square == x:
            return mid
        if square < x:
            result = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return result

# Example: int_sqrt(8) -> 2
# Time: O(log x), Space: O(1). Binary search over [1, x//2] tracking last valid mid.

def single_element_sorted(arr):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            lo = mid + 2
        else:
            hi = mid
    return arr[lo]

# Example: single_element_sorted([1,1,3,3,4,4,7,8,8]) -> 7
# Time: O(log n), Space: O(1). Align mid to even index; pairs start at even positions.

