def two_sum_sorted(arr, target):
    for i in range(len(arr)):
        complement = target - arr[i]
        lo, hi = i + 1, len(arr) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == complement:
                return [i, mid]
            if arr[mid] < complement:
                lo = mid + 1
            else:
                hi = mid - 1
    return [-1, -1]

# Example: two_sum_sorted([2,7,11,15], 9) -> [0, 1]
# Time: O(n log n), Space: O(1). For each index, binary-search the complement in the rest.

def find_duplicate_sorted(arr):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] == arr[mid + 1]:
            return arr[mid]
        if (mid - lo + 1) <= (arr[mid] - arr[lo] + 1):
            lo = mid + 1
        else:
            hi = mid
    return arr[lo]

# Example: find_duplicate_sorted([1,3,4,4,5,6,7]) -> 4
